#include <bits/stdc++.h>using namespace std; int main() {    int T;    cin >> T;     while (T--) {        int n;        cin >> n;        string s;        cin >> s;         vector<int> pos;        for (int i = 0; i < n; i++) {            if (s[i] == '1') pos.push_back(i);        }         int ans = 0;         if (pos.empty()) {            cout << (n + 2) / 3 << endl;            continue;        }         // Prefix zeros        int prefix = pos[0];        ans += (prefix + 1)/ 3;         // Middle gaps        for (int i = 0; i + 1 < pos.size(); i++) {            int gap = pos[i + 1] - pos[i] - 1;                           ans += (gap) / 3;                    }         // Suffix zeros        int suffix = n - 1 - pos.back() + 1;        ans += (suffix) / 3.0;         cout << ans + pos.size() << endl;    }}